using System.Security.Claims; using Asp.Versioning; using LostFound.Application.Contracts; using LostFound.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace LostFound.Api.Controllers;
[Authorize,ApiController,ApiVersion(1),Route("api/v{version:apiVersion}/notifications")] public sealed class NotificationsController(LostFoundDbContext db):ControllerBase{private Guid UserId=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet]public async Task<ActionResult<PagedResponse<NotificationResponse>>> List(int page=1,int pageSize=30,CancellationToken ct=default){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Notifications.AsNoTracking().Where(x=>x.UserId==UserId).OrderByDescending(x=>x.CreatedAtUtc);var total=await q.CountAsync(ct);var rows=await q.Skip((page-1)*pageSize).Take(pageSize).Select(x=>new NotificationResponse(x.Id,x.Type,x.PayloadJson,x.CreatedAtUtc,x.ReadAtUtc)).ToListAsync(ct);return Ok(new PagedResponse<NotificationResponse>(rows,page,pageSize,total));}[HttpGet("unread-count")]public async Task<ActionResult<int>> Count(CancellationToken ct)=>Ok(await db.Notifications.CountAsync(x=>x.UserId==UserId&&x.ReadAtUtc==null,ct));[HttpPost("{id:guid}/read")]public async Task<IActionResult> Read(Guid id,CancellationToken ct){var n=await db.Notifications.SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==UserId,ct);if(n is null)return NotFound();n.ReadAtUtc??=DateTime.UtcNow;await db.SaveChangesAsync(ct);return NoContent();}[HttpPost("read-all")]public async Task<IActionResult> All(CancellationToken ct){await db.Notifications.Where(x=>x.UserId==UserId&&x.ReadAtUtc==null).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.ReadAtUtc,DateTime.UtcNow),ct);return NoContent();}}
